const fs = require('fs');
const path = require('path');

const dir = 'c:/Users/admin/Desktop/billing_inventory/backend';
const files = fs.readdirSync(dir).filter(f => f.startsWith('edits-') && f.endsWith('.json'));

console.log('Found', files.length, 'edit JSON files.');

const summary = [];

for (const file of files) {
  const filePath = path.join(dir, file);
  const data = JSON.parse(fs.readFileSync(filePath, 'utf-8'));
  if (data.length === 0) continue;

  // Get target files modified
  const targetFiles = new Set();
  data.forEach(edit => {
    if (edit.args && edit.args.TargetFile) {
      targetFiles.add(edit.args.TargetFile);
    }
  });

  summary.push({
    file,
    editsCount: data.length,
    targets: Array.from(targetFiles),
    steps: data.map(d => d.step_index)
  });
}

console.log(JSON.stringify(summary, null, 2));
